```cpp
#include <iostream>
#include <string>
#include <sstream>

std::string markdownToHtml(const std::string& markdown) {
    // Convert markdown to HTML using a markdown library
    // This is a simplified example and may not support all markdown features
    // For a more robust solution, consider using a dedicated markdown-to-html library

    std::string html;
    std::stringstream ss(markdown);
    std::string line;
    while (std::getline(ss, line)) {
        html += line + "\n";
    }
    return html;
}

int main() {
    std::string markdown = "# Hello World\n\nThis is a test paragraph.";
    std::string html = markdownToHtml(markdown);
    std::cout << html << std::endl;
    return 0;
}
```

